CREATE OR ALTER PROCEDURE [dbo].[uspRecipe_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @DishId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @YieldUnitId UNIQUEIDENTIFIER = NULL
	, @VersionCode NVARCHAR(MAX) = NULL
	, @YieldQuantity DECIMAL(18,4) = NULL
	, @EffectiveFrom DATETIME = NULL
	, @EffectiveTo DATETIME = NULL
	, @IsActive BIT = NULL
	, @Instructions NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[DishId]
			, t.[VersionNo]
			, t.[YieldPercent]
			, t.[StandardOutputQty]
			, t.[EffectiveFrom]
			, t.[EffectiveTo]
			, t.[Status]
			, t.[ApprovedBy]
			, t.[ApprovedAt]
			, t.[Note]
			, t.[VersionCode]
			, t.[YieldQuantity]
			, t.[YieldUnitId]
			, t.[IsActive]
			, t.[Instructions]
			, t.[SnapshotJson]
			, t.[LockedAt]
			, t.[LockedBy]
			, t.[CreatedDate]
		FROM [dbo].[Recipe] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[VersionCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@DishId IS NULL OR t.[DishId] = @DishId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@YieldUnitId IS NULL OR t.[YieldUnitId] = @YieldUnitId)
			AND (ISNULL(@VersionCode, '') = '' OR t.[VersionCode] LIKE CONCAT('%', @VersionCode, '%'))
			AND (@YieldQuantity IS NULL OR t.[YieldQuantity] = @YieldQuantity)
			AND (@EffectiveFrom IS NULL OR t.[EffectiveFrom] = @EffectiveFrom)
			AND (@EffectiveTo IS NULL OR t.[EffectiveTo] = @EffectiveTo)
			AND (@IsActive IS NULL OR t.[IsActive] = @IsActive)
			AND (ISNULL(@Instructions, '') = '' OR t.[Instructions] LIKE CONCAT('%', @Instructions, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dishId' THEN r.[DishId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dishId' THEN r.[DishId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'versionNo' THEN r.[VersionNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'versionNo' THEN r.[VersionNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'yieldPercent' THEN r.[YieldPercent] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'yieldPercent' THEN r.[YieldPercent] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'standardOutputQty' THEN r.[StandardOutputQty] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'standardOutputQty' THEN r.[StandardOutputQty] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvedBy' THEN r.[ApprovedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvedBy' THEN r.[ApprovedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvedAt' THEN r.[ApprovedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvedAt' THEN r.[ApprovedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'versionCode' THEN r.[VersionCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'versionCode' THEN r.[VersionCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'yieldQuantity' THEN r.[YieldQuantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'yieldQuantity' THEN r.[YieldQuantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'yieldUnitId' THEN r.[YieldUnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'yieldUnitId' THEN r.[YieldUnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isActive' THEN r.[IsActive] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isActive' THEN r.[IsActive] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'instructions' THEN r.[Instructions] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'instructions' THEN r.[Instructions] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'snapshotJson' THEN r.[SnapshotJson] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'snapshotJson' THEN r.[SnapshotJson] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lockedAt' THEN r.[LockedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lockedAt' THEN r.[LockedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lockedBy' THEN r.[LockedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lockedBy' THEN r.[LockedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
